def invoice_total(lines, customer):
    total = 0
    for line in lines:
        if line.get('kind') == 'item':
            if customer.get('trade'):
                if line['qty'] > 100:
                    total += line['price'] * line['qty'] * 0.8
                else:
                    total += line['price'] * line['qty'] * 0.9
            else:
                if line['qty'] > 100:
                    total += line['price'] * line['qty'] * 0.95
                else:
                    total += line['price'] * line['qty']
        elif line.get('kind') == 'fee':
            if not customer.get('waive_fees'):
                total += line['price']
    if customer.get('country') == 'GB':
        total *= 1.2
    return round(total, 2)

